#include "query.h"
#include <sqlite3.h>
#include <limits.h>
#include <stdint.h>
#include <string.h>
static int same_key(const drbz_query_cache *c,const unsigned char *sql,size_t n){return c->valid&&c->key&&c->key_len==n&&!memcmp(c->key,sql,n);}
static int reserve(drbz_query_cache *c,size_t needed){if(needed<=c->capacity)return SQLITE_OK;size_t next=c->capacity?c->capacity:256;while(next<needed){if(next>SIZE_MAX/2){next=needed;break;}next*=2;}void *p=sqlite3_realloc64(c->buffer,(sqlite3_uint64)next);if(!p)return SQLITE_NOMEM;c->buffer=p;c->capacity=next;return SQLITE_OK;}
static int append_first(drbz_query_cache *c,sqlite3_stmt *stmt){uint64_t header=UINT64_MAX;const unsigned char *bytes=NULL;size_t n=0;if(sqlite3_column_type(stmt,0)!=SQLITE_NULL){bytes=sqlite3_column_text(stmt,0);if(!bytes)return SQLITE_NOMEM;int x=sqlite3_column_bytes(stmt,0);if(x<0)return SQLITE_TOOBIG;n=(size_t)x;header=(uint64_t)n;}if(c->output_len>SIZE_MAX-sizeof header||c->output_len+sizeof header>SIZE_MAX-n)return SQLITE_TOOBIG;size_t total=c->output_len+sizeof header+n;int rc=reserve(c,total);if(rc!=SQLITE_OK)return rc;memcpy(c->buffer+c->output_len,&header,sizeof header);c->output_len+=sizeof header;if(n){memcpy(c->buffer+c->output_len,bytes,n);c->output_len+=n;}++c->rows;return SQLITE_OK;}
static drbz_query_result run_stmt(drbz_query_cache *c,sqlite3_stmt *stmt,int hit){drbz_query_result r={SQLITE_OK,SQLITE_OK,0,hit};for(;;){int rc=sqlite3_step(stmt);if(rc==SQLITE_DONE)break;if(rc!=SQLITE_ROW){r.code=rc;break;}r.code=append_first(c,stmt);if(r.code!=SQLITE_OK)break;}r.rows=c->rows;r.reset_code=sqlite3_reset(stmt);if(r.code==SQLITE_OK&&r.reset_code!=SQLITE_OK)r.code=r.reset_code;if(r.code!=SQLITE_OK){c->output_len=0;c->rows=0;}return r;}
void drbc_query_cache_init(drbz_query_cache *c,sqlite3 *db){*c=(drbz_query_cache){.db=db};}
int drbc_query_cache_clear(drbz_query_cache *c){int rc=c->stmt?sqlite3_finalize(c->stmt):SQLITE_OK;sqlite3_free(c->key);sqlite3_free(c->buffer);sqlite3 *db=c->db;uint64_t prepares=c->prepares,hits=c->hits;*c=(drbz_query_cache){.db=db,.prepares=prepares,.hits=hits};return rc;}
static int prepare_cached(drbz_query_cache *c,const unsigned char *sql,size_t n,int *hit){*hit=0;if(!c->db||n>INT_MAX||(n&&memchr(sql,0,n)))return n>INT_MAX?SQLITE_TOOBIG:SQLITE_MISUSE;if(c->stmt&&sqlite3_stmt_busy(c->stmt))return SQLITE_MISUSE;if(same_key(c,sql,n)){++c->hits;*hit=1;return SQLITE_OK;}sqlite3_stmt *stmt=NULL;int rc=sqlite3_prepare_v3(c->db,(const char *)sql,(int)n,SQLITE_PREPARE_PERSISTENT,&stmt,NULL);if(rc!=SQLITE_OK)return rc;unsigned char *key=sqlite3_malloc64(n?(sqlite3_uint64)n:1);if(!key){sqlite3_finalize(stmt);return SQLITE_NOMEM;}if(n)memcpy(key,sql,n);sqlite3_stmt *old_stmt=c->stmt;unsigned char *old_key=c->key;c->stmt=stmt;c->key=key;c->key_len=n;c->valid=1;++c->prepares;int cleanup=old_stmt?sqlite3_finalize(old_stmt):SQLITE_OK;sqlite3_free(old_key);return cleanup;}
drbz_query_result drbc_query_pack(drbz_query_cache *c,const unsigned char *sql,size_t n){c->output_len=0;c->rows=0;int hit=0,rc=prepare_cached(c,sql,n,&hit);if(rc!=SQLITE_OK)return(drbz_query_result){rc,SQLITE_OK,0,hit};if(!c->stmt)return(drbz_query_result){SQLITE_OK,SQLITE_OK,0,hit};return run_stmt(c,c->stmt,hit);}
void drbc_query_output(const drbz_query_cache *c,const unsigned char **bytes,size_t *length,size_t *rows){*bytes=c->buffer;*length=c->output_len;*rows=c->rows;}
